use std::collections::HashMap;
use std::io::{Read, Write};

fn main() {
    let mut raw = Vec::new();
    std::io::stdin().read_to_end(&mut raw).unwrap();
    let nl = raw.iter().position(|&b| b == b'\n').unwrap_or(raw.len());
    let k: usize = String::from_utf8_lossy(&raw[..nl]).trim().parse().unwrap_or(0);
    let rest = if nl < raw.len() { &raw[nl + 1..] } else { &raw[..0] };
    let mut m: HashMap<Vec<u8>, u64> = HashMap::new();
    let mut cur: Vec<u8> = Vec::new();
    for &b in rest.iter().chain(std::iter::once(&b' ')) {
        if b.is_ascii_alphanumeric() {
            cur.push(b.to_ascii_lowercase());
        } else if !cur.is_empty() {
            *m.entry(std::mem::take(&mut cur)).or_insert(0) += 1;
        }
    }
    let mut v: Vec<(Vec<u8>, u64)> = m.into_iter().collect();
    v.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    let out = std::io::stdout();
    let mut o = out.lock();
    for (w, c) in v.into_iter().take(k) {
        o.write_all(&w).unwrap();
        writeln!(o, " {}", c).unwrap();
    }
}

